import icontract
from typing import List


def idx_of(xs: List[int], v: int) -> int:
    # index of the first occurrence of v in xs, or len(xs) if v does not occur
    return xs.index(v) if v in xs else len(xs)


@icontract.ensure(lambda s, result: all(x in s for x in result))
@icontract.ensure(lambda s, result: all(x in result for x in s))
@icontract.ensure(lambda result: all(result.count(x) == 1 for x in result))
@icontract.ensure(lambda s, result: all(
    idx_of(s, result[i]) < idx_of(s, result[j]) for i in range(len(result)) for j in range(i + 1, len(result))))
def SetToSeq(s: List[int]) -> List[int]:
    result = []
    for x in s:
        if x not in result:
            result.append(x)
    return result
